import pyomo.environ as pyo

DATA = {
    "nodes": [0, 1, 2, 3, 4],
    "num_select": 2,
    "weights": {
        (0, 1): 22, (0, 2): 19, (0, 3): 24, (0, 4): 22,
        (1, 0): 19, (1, 2): 23, (1, 3): 16, (1, 4): 25,
        (2, 0): 19, (2, 1): 16, (2, 3): 19, (2, 4): 21,
        (3, 0): 25, (3, 1): 19, (3, 2): 21, (3, 4): 17,
        (4, 0): 19, (4, 1): 22, (4, 2): 19, (4, 3): 21,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.NODES = pyo.Set(initialize=d["nodes"])
    model.PAIRS = pyo.Set(
        initialize=[(i, j) for (i, j) in d["weights"].keys()],
        dimen=2,
    )

    model.select = pyo.Var(model.NODES, within=pyo.Binary)
    model.pair_used = pyo.Var(model.PAIRS, within=pyo.Binary)

    def obj_rule(m):
        return sum(d["weights"][(i, j)] * m.pair_used[i, j] for (i, j) in m.PAIRS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def select_count_rule(m):
        return sum(m.select[i] for i in m.NODES) == d["num_select"]

    model.select_count = pyo.Constraint(rule=select_count_rule)

    def pair_le_first_rule(m, i, j):
        return m.pair_used[i, j] <= m.select[i]

    model.pair_le_first = pyo.Constraint(model.PAIRS, rule=pair_le_first_rule)

    def pair_le_second_rule(m, i, j):
        return m.pair_used[i, j] <= m.select[j]

    model.pair_le_second = pyo.Constraint(model.PAIRS, rule=pair_le_second_rule)

    def pair_ge_both_rule(m, i, j):
        return m.pair_used[i, j] >= m.select[i] + m.select[j] - 1

    model.pair_ge_both = pyo.Constraint(model.PAIRS, rule=pair_ge_both_rule)

    return model
